with unpacked as (select id, customer_id, created_at, coupon_codes, items, array_contains(coupon_codes, 'VIP') as used_vip, coalesce(ship_to.zip, 'UNKNOWN') as zip_or_unknown, attributes['utm_source'] as utm_source from carts where customer_id in (10, 26, 35, 39)) select date_trunc('day', created_at) as activity_day, customer_id, min(created_at) as first_created_at, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes, max(created_at) as ended_at, count(distinct zip_or_unknown) as distinct_zip_or_unknowns, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes_2, max(created_at) as ended_at_2, grouping(date_trunc('day', created_at)) as gid from unpacked group by cube (date_trunc('day', created_at), customer_id) order by span_minutes_2 nulls last
